915	/****************************************************************************
916	 * Name: sai_worker
917	 *
918	 * Description:
919	 *   Transfer done worker
920	 *
921	 * Input Parameters:
922	 *   arg - the SAI device instance cast to void*
923	 *
924	 * Returned Value:
925	 *   None
926	 *
927	 ****************************************************************************/
928	
929	static void sai_worker(void *arg)
930	{
931	  struct stm32f7_sai_s *priv = (struct stm32f7_sai_s *)arg;
932	  struct sai_buffer_s *bfcontainer;
933	  irqstate_t flags;
934	
935	  DEBUGASSERT(priv);
936	
937	  /* When the transfer was started, the active buffer containers were removed
938	   * from the pend queue and saved in the act queue.  We get here when the
939	   * transfer is finished... either successfully, with an error, or with a
940	   * timeout.
941	   *
942	   * In any case, the buffer containers in act will be moved to the end
943	   * of the done queue and act will be emptied before this worker is
944	   * started.
945	   */
946	
947	  i2sinfo("act.head=%p done.head=%p\n", priv->act.head, priv->done.head);
948	
949	  /* Check if IDLE */
950	
951	  if (sq_empty(&priv->act))
952	    {
953	      /* Then start the next transfer.  This must be done with interrupts
954	       * disabled.
955	       */
956	
957	      flags = enter_critical_section();
958	#ifdef CONFIG_STM32F7_SAI_DMA
959	      sai_dma_setup(priv);
960	#endif
961	      leave_critical_section(flags);
962	    }
963	
964	  /* Process each buffer in the done queue */
965	
966	  while (sq_peek(&priv->done) != NULL)
967	    {
968	      /* Remove the buffer container from the done queue.  NOTE that
969	       * interrupts must be enabled to do this because the done queue is
970	       * also modified from the interrupt level.
971	       */
972	
973	      flags = enter_critical_section();
974	      bfcontainer = (struct sai_buffer_s *)sq_remfirst(&priv->done);
975	      leave_critical_section(flags);
976	
977	      /* Perform the transfer done callback */
978	
979	      DEBUGASSERT(bfcontainer && bfcontainer->callback);
980	      bfcontainer->callback(&priv->dev, bfcontainer->apb,
981	                            bfcontainer->arg, bfcontainer->result);
982	
983	      /* Release our reference on the audio buffer.  This may very likely
984	       * cause the audio buffer to be freed.
985	       */
986	
987	      apb_free(bfcontainer->apb);
988	
989	      /* And release the buffer container */
990	
991	      sai_buf_free(priv, bfcontainer);
992	    }
993	}
