995	/****************************************************************************
996	 * Name: sai_schedule
997	 *
998	 * Description:
999	 *   An transfer completion or timeout has occurred.  Schedule processing on
1000	 *   the working thread.
1001	 *
1002	 * Input Parameters:
1003	 *   priv   - SAI state instance
1004	 *   result - The result of the transfer
1005	 *
1006	 * Returned Value:
1007	 *   None
1008	 *
1009	 * Assumptions:
1010	 *   - Interrupts are disabled
1011	 *   - The timeout has been canceled.
1012	 *
1013	 ****************************************************************************/
1014	
1015	static void sai_schedule(struct stm32f7_sai_s *priv, int result)
1016	{
1017	  struct sai_buffer_s *bfcontainer;
1018	  int ret;
1019	
1020	  /* Move all entries from the act queue to the done queue */
1021	
1022	  while (!sq_empty(&priv->act))
1023	    {
1024	      /* Remove the next buffer container from the act list */
1025	
1026	      bfcontainer = (struct sai_buffer_s *)sq_remfirst(&priv->act);
1027	
1028	      /* Report the result of the transfer */
1029	
1030	      bfcontainer->result = result;
1031	
1032	      /* Add the completed buffer container to the tail of the done queue */
1033	
1034	      sq_addlast((sq_entry_t *)bfcontainer, &priv->done);
1035	    }
1036	
1037	  /* If the worker has completed running, then reschedule the working thread.
1038	   * REVISIT:  There may be a race condition here.  So we do nothing is the
1039	   * worker is not available.
1040	   */
1041	
1042	  if (work_available(&priv->work))
1043	    {
1044	      /* Schedule the done processing to occur on the worker thread. */
1045	
1046	      ret = work_queue(HPWORK, &priv->work, sai_worker, priv, 0);
1047	      if (ret != 0)
1048	        {
1049	          i2serr("ERROR: Failed to queue work: %d\n", ret);
1050	        }
1051	    }
1052	}
