/* SAI DMA priority */

#ifdef CONFIG_STM32H7_SAI_DMAPRIO
#  define SAI_DMA_PRIO       CONFIG_STM32H7_SAI_DMAPRIO
#else
#  define SAI_DMA_PRIO       DMA_SCR_PRIVERYHI
#endif

