728	
729	      DEBUGASSERT(bfcontainer && bfcontainer->callback);
730	      bfcontainer->callback(&priv->dev, bfcontainer->apb,
731	                            bfcontainer->arg, bfcontainer->result);
732	
733	      /* Release our reference on the audio buffer.  This may very likely
734	       * cause the audio buffer to be freed.
735	       */
