1222	/****************************************************************************
1223	 * Name: sai_pdmconfig
1224	 *
1225	 * Description:
1226	 *   Program the PDM interface for a single microphone on bitstream 2.
1227	 *
1228	 *   The microphone drives its data on the falling edge of the clock it
1229	 *   receives, so the serial interface samples on the rising edge
1230	 *   (SITP-equivalent setting) and the clock is configured to be free-running
1231	 *   through CK2, which is the line the board wires to the microphone.
1232	 *
1233	 ****************************************************************************/
1234	
1235	static void sai_pdmconfig(struct stm32h7_sai_s *priv)
1236	{
1237	  uint32_t regval;
1238	
1239	  /* PDMCR lives in the global block, which is shared by both sub-blocks */
1240	
1241	  regval  = getreg32(priv->pdmbase + STM32H7_SAI_PDMCR_OFFSET);
1242	  regval &= ~SAI_PDMCR_PDMEN;
1243	  putreg32(regval, priv->pdmbase + STM32H7_SAI_PDMCR_OFFSET);
1244	
1245	  regval &= ~(SAI_PDMCR_MICNBR_MASK | SAI_PDMCR_CKEN1 | SAI_PDMCR_CKEN2 |
1246	              SAI_PDMCR_CKEN3 | SAI_PDMCR_CKEN4);
1247	  regval |= SAI_PDMCR_CKEN2 | SAI_PDMCR_MICNBR(1);
1248	  putreg32(regval, priv->pdmbase + STM32H7_SAI_PDMCR_OFFSET);
1249	
1250	  putreg32(SAI_PDMDLY_NODELAY, priv->pdmbase + STM32H7_SAI_PDMDLY_OFFSET);
1251	
1252	  regval |= SAI_PDMCR_PDMEN;
1253	  putreg32(regval, priv->pdmbase + STM32H7_SAI_PDMCR_OFFSET);
1254	}
