/****************************************************************************
 * Name: sai_mckdivider
 *
 * Description:
 *   Program MCKDIV from the kernel clock and the required frame rate.
 *
 *   Two divider formulas exist, selected by NODIV:
 *
 *     NODIV=0: MCLK is generated and must be a multiple of the frame rate,
 *              with 256 * FS being the conventional target.
 *     NODIV=1: the bit clock is derived directly from the kernel clock and
 *              divided by the frame length, which is what PDM mode needs:
 *              the PDM interface defines its own frame layout, so the 256 *
 *              FS relationship does not apply.
 *
 *   PDM therefore uses the NODIV=1 branch with the PDM frame length, and
 *   everything else uses the NODIV=0 branch.  Only meaningful in master mode;
 *   hardware ignores the field in slave mode, so writing it is harmless.
 *
 ****************************************************************************/

static void sai_mckdivider(struct stm32h7_sai_s *priv)
{
  uint32_t framelen;
  uint32_t mckdiv;
  uint32_t tmpval;

  DEBUGASSERT(priv && priv->samplerate > 0 && priv->frequency > 0);

  if (priv->pdm)
    {
      /* PDM: one frame carries the bits of a single microphone pair per
       * clock line, so the frame length is the ratio between the bit clock
       * and the audio frame rate, as set up in sai_pdmconfig().
       */

      framelen = SAI_PDM_FRAME_LENGTH;

      /* MCKDIV = CK / (FS * FRL), kept in tenths for significant digits */

      tmpval = (priv->frequency * 10) / (priv->samplerate * framelen);
      mckdiv = tmpval / 10;

      if ((tmpval % 10) > 8)
        {
          mckdiv += 1;
        }

      if (mckdiv < SAI_MCKDIV_MIN)
        {
          mckdiv = SAI_MCKDIV_MIN;
        }
      else if (mckdiv > SAI_MCKDIV_MAX)
        {
          mckdiv = SAI_MCKDIV_MAX;
        }

      sai_modifyreg(priv, STM32H7_SAI_CR1_OFFSET,
                    SAI_CR1_MCKDIV_MASK | SAI_CR1_NODIV | SAI_CR1_OSR,
                    SAI_CR1_MCKDIV(mckdiv) | SAI_CR1_NODIV);
      return;
    }

  /* PCM: MCLK = CK / (MCKDIV * 2) and MCLK is targeted at 256 * FS, so
   *
   *   MCKDIV = CK / (FS * 2 * 256)
   *
   * An odd over sampling ratio halves the achievable MCLK, so the divider is
   * doubled in that case.
   */

  tmpval = (priv->frequency * 10) /
           (priv->samplerate * 2 * 256 * (priv->or ? 2 : 1));
  mckdiv = tmpval / 10;

  if ((tmpval % 10) > 8)
    {
      mckdiv += 1;
    }

  if (mckdiv < SAI_MCKDIV_MIN)
    {
      mckdiv = SAI_MCKDIV_MIN;
    }
  else if (mckdiv > SAI_MCKDIV_MAX)
    {
      mckdiv = SAI_MCKDIV_MAX;
    }

