/****************************************************************************
 * app/velaguard/vgpdmdump.c
 *
 * BVO-03b 板载麦克风原始 PDM 采集验证工具。
 *
 * 从 /dev/i2schar0 取一段定长的原始 PDM 位流，写到文件，并打印足以判断
 * 通路是否真的工作的统计量。这只用于 bring-up，不属于产品音频路径：
 * 不做抽取滤波，不接语音，不改变任何配置或点表。
 *
 * 判据说明。DMA 中断递增或缓冲区非零，只能证明总线上的传输在动。要认定
 * 麦克风真的在工作，还需要同时看到：
 *   - 非零字节占比接近 50%（PDM 位流的占空比在静音时约一半）；
 *   - 字节取值分布不是单一常量（全 0x00 或 0xFF 说明数据线被拉死）；
 *   - 说话与静音两种条件下的统计量有可观察差异。
 * 因此本工具打印直方图和熵，而不只打印首字节。
 ****************************************************************************/

#include <nuttx/config.h>

#ifdef CONFIG_VG_PDM_DUMP

#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <string.h>
#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <math.h>

#include <nuttx/audio/i2s.h>

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* 采集长度上界。16 kHz 采样率、64 倍抽取下，每毫秒产生约 128 字节 PDM。
 * 32 KiB 约等于 256 ms，够判断通路，又不至于在 NSH 里卡太久。缓冲区从
 * 堆上按 cache 行对齐分配，不静态占用 SRAM。
 */

#define VG_PDM_MAXBYTES   (32768)

/****************************************************************************
 * Private Types
 ****************************************************************************/

/* 一次采集的统计量。daemon 只读地算出来给操作者看，不含结论性判断。
 */

struct vg_pdm_stats
{
  size_t   nbytes;        /* 实际收到的字节数 */
  size_t   nzero;         /* 值为 0x00 的字节数 */
  size_t   nonzero;       /* 非零字节数 */
  size_t   nff;           /* 值为 0xFF 的字节数 */
  size_t   nbits;         /* 置位的比特总数 */
  double   ones_ratio;    /* 置位比特占比，静音时接近 0.5 */
  double   entropy;       /* 每字节香农熵，单位 bit，上限 8 */
  uint8_t  minbyte;
  uint8_t  maxbyte;
  uint8_t  hist[16];      /* 高 4 位直方图，16 个桶 */
};

/****************************************************************************
 * Private Data
 ****************************************************************************/

static FAR struct ap_buffer_s *g_apb;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: vg_pdm_usage
 ****************************************************************************/

static void vg_pdm_usage(void)
{
  printf("usage: vgpdmdump [-n bytes] [-f path] [-q]\n"
         "  -n bytes  capture length, 64..%d, default 16384\n"
         "  -f path   output file, default /data/pdm.raw\n"
         "  -q        do not write a file, statistics only\n",
         VG_PDM_MAXBYTES);
}

/****************************************************************************
 * Name: vg_pdm_stats
 *
 * Description:
 *   统计一段 PDM 位流。所有字段都从同一遍扫描得出，避免缓冲区被改写后
 *   各字段来自不同时刻。
 *
 ****************************************************************************/

static void vg_pdm_stats(FAR const uint8_t *buf, size_t nbytes,
                         FAR struct vg_pdm_stats *st)
{
  size_t   i;
  uint32_t j;
  uint16_t hist[256];
  double   h;

  memset(st, 0, sizeof(*st));
  memset(hist, 0, sizeof(hist));

  st->nbytes  = nbytes;
  st->minbyte = 0xff;
  st->maxbyte = 0x00;

  for (i = 0; i < nbytes; i++)
    {
      uint8_t b = buf[i];

      hist[b]++;
      st->nbits += __builtin_popcount(b);

      if (b == 0x00)
        {
          st->nzero++;
        }
      else
        {
          st->nonzero++;
        }

      if (b == 0xff)
        {
          st->nff++;
        }

      if (b < st->minbyte)
        {
          st->minbyte = b;
        }

      if (b > st->maxbyte)
        {
          st->maxbyte = b;
        }

      st->hist[b >> 4]++;
    }

  if (nbytes > 0)
    {
      st->ones_ratio = (double)st->nbits / ((double)nbytes * 8.0);
    }

  /* 香农熵按字节取值计算。真实位流接近 8 bit；常量数据线为 0。
   */

  h = 0.0;
  for (i = 0; i < 256; i++)
    {
      if (hist[i] != 0)
        {
          double p = (double)hist[i] / (double)nbytes;
          h -= p * (log(p) / log(2.0));
        }
    }

  st->entropy = h;
}

/****************************************************************************
 * Name: vg_pdm_report
 ****************************************************************************/

static void vg_pdm_report(FAR const struct vg_pdm_stats *st)
{
  int i;

  printf("vgpdmdump: %zu bytes\n", st->nbytes);
  printf("  zero=%.1f%%  ones=%.3f  entropy=%.3f bit/byte\n",
         st->nbytes ? (100.0 * (double)st->nzero / (double)st->nbytes) : 0.0,
         st->ones_ratio, st->entropy);
  printf("  min=0x%02x max=0x%02x ff=%zu\n",
         st->minbyte, st->maxbyte, st->nff);
  printf("  nibble histogram:");

  for (i = 0; i < 16; i++)
    {
      printf(" %s%u", (i == 0) ? "" : ",", (unsigned int)st->hist[i]);
    }

  printf("\n");
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: vgpdmdump_main
 *
 * Description:
 *   NSH 入口。打开采集设备，投递一次定长接收，等回调完成后统计并落盘。
 *
 ****************************************************************************/

int main(int argc, FAR char *argv[])
{
  FAR const char *path = "/data/pdm.raw";
  size_t nbytes = 16384;
  bool quiet = false;
  struct ap_buffer_s *apb;
  struct vg_pdm_stats stats;
  struct audio_buf_desc_s bufdesc;
  int fd;
  int ret;
  int i;

  for (i = 1; i < argc; i++)
    {
      if (strcmp(argv[i], "-n") == 0 && i + 1 < argc)
        {
          long v = strtol(argv[++i], NULL, 0);

          if (v < 64 || v > VG_PDM_MAXBYTES)
            {
              fprintf(stderr, "vgpdmdump: -n out of range\n");
              return EXIT_FAILURE;
            }

          nbytes = (size_t)v;
        }
      else if (strcmp(argv[i], "-f") == 0 && i + 1 < argc)
        {
          path = argv[++i];
        }
      else if (strcmp(argv[i], "-q") == 0)
        {
          quiet = true;
        }
      else
        {
          vg_pdm_usage();
          return EXIT_FAILURE;
        }
    }

  /* 长度取整到 DMA 传输单位（16 位）的整数倍，避免最后一拍被截断。
   */

  nbytes &= ~(size_t)1;

  /* 缓冲区必须按 cache 行对齐：驱动在接收前后都做 cache 维护，未对齐会让
   * 相邻数据被一并处理。
   */

  memset(&bufdesc, 0, sizeof(bufdesc));
  bufdesc.numbytes    = nbytes;
  bufdesc.u.pbuffer   = &apb;
  ret = apb_alloc(&bufdesc);
  if (ret < 0)
    {
      fprintf(stderr, "vgpdmdump: apb_alloc failed: %d\n", ret);
      return EXIT_FAILURE;
    }

  fd = open("/dev/i2schar0", O_RDONLY);
  if (fd < 0)
    {
      fprintf(stderr, "vgpdmdump: open /dev/i2schar0 failed: %d\n", errno);
      apb_free(apb);
      return EXIT_FAILURE;
    }

  /* i2schar 的 read 接收整个 ap_buffer_s 结构体地址，同步等回调完成。
   * 返回后 apb 里就是驱动写进去的原始位流。
   */

  ret = read(fd, (FAR char *)apb, sizeof(*apb) + nbytes);
  if (ret < 0)
    {
      fprintf(stderr, "vgpdmdump: read failed: %d\n", errno);
      close(fd);
      return EXIT_FAILURE;
    }

  close(fd);

  vg_pdm_stats(apb->samp, nbytes, &stats);
  vg_pdm_report(&stats);

  if (!quiet)
    {
      int out = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);

      if (out < 0)
        {
          fprintf(stderr, "vgpdmdump: open %s failed: %d\n", path, errno);
          apb_free(apb);
          return EXIT_FAILURE;
        }

      ret = write(out, apb->samp, nbytes);
      if (ret != (int)nbytes)
        {
          fprintf(stderr, "vgpdmdump: short write %d of %zu: %d\n",
                  ret, nbytes, errno);
          close(out);
          apb_free(apb);
          return EXIT_FAILURE;
        }

      close(out);
      printf("vgpdmdump: wrote %zu bytes to %s\n", nbytes, path);
    }

  apb_free(apb);
  return EXIT_SUCCESS;
}

#endif /* CONFIG_VG_PDM_DUMP */

