/****************************************************************************
 * Name: vg_pdm_hexdump
 *
 * Description:
 *   以十六进制打印一段前缀。板上没有 xxd 一类工具，需要把原始字节带回
 *   主机核对时只能靠这个输出。
 *
 ****************************************************************************/

static void vg_pdm_hexdump(FAR const uint8_t *buf, size_t nbytes)
{
  size_t i;

  for (i = 0; i < nbytes; i++)
    {
      if ((i & 15) == 0)
        {
          printf("  %04zu:", i);
        }

      printf(" %02x", buf[i]);

      if ((i & 15) == 15 || i + 1 == nbytes)
        {
          printf("\n");
        }
    }
}

