  /* 按毫秒分块求瞬时电平。PDM 的输出密度等于模拟输入归一化到 [0,1]，
   * 所以一块内“1”的占比偏离 0.5 的幅度就是这一毫秒的信号幅度。静音时
   * 只剩量化噪声，偏离很小；说话时会有明显起伏。
   *
   * 用偏离的均方根而不是峰峰值：峰值对单个异常块太敏感。
   */

  st->blk_min = 1.0;
  st->blk_max = 0.0;

  {
    size_t nblocks = nbytes / VG_PDM_BLOCK_BYTES;
    double sumsq = 0.0;
    size_t b;

    for (b = 0; b < nblocks; b++)
      {
        const uint8_t *p = &buf[b * VG_PDM_BLOCK_BYTES];
        size_t ones = 0;
        double dens;
        double dev;
        size_t k;

        for (k = 0; k < VG_PDM_BLOCK_BYTES; k++)
          {
            ones += (size_t)__builtin_popcount(p[k]);
          }

        dens = (double)ones /
               ((double)VG_PDM_BLOCK_BYTES * 8.0);
        dev  = dens - 0.5;

        sumsq += dev * dev;

        if (dev < 0.0)
          {
            dev = -dev;
          }

        if (dev > st->level_peak)
          {
            st->level_peak = dev;
          }

        if (dens < st->blk_min)
          {
            st->blk_min = dens;
          }

        if (dens > st->blk_max)
          {
            st->blk_max = dens;
          }
      }

    st->nblocks = nblocks;

    if (nblocks > 0)
      {
        st->level_rms = sqrt(sumsq / (double)nblocks);
      }
  }
}

