  flags = enter_critical_section();
  sq_addlast((sq_entry_t *)bfcontainer, &priv->pend);

  /* Then start the next transfer.  If there is already a transfer in
   * progress, then this will do nothing.
   *
   * A setup failure has to be passed back to the caller.  Returning OK while
   * the transfer never starts leaves the caller waiting for a completion
   * callback that will not arrive; an assertion here would be compiled out
   * of a release build and the error would vanish.  The queued container
   * holds a reference to the audio buffer, so it has to be released too.
   */

#ifdef CONFIG_STM32H7_SAI_DMA
  ret = sai_dma_setup(priv);
#else
  ret = -ENOSYS;
#endif

  if (ret < 0)
    {
      /* sai_dma_setup() consumes the pending entry when it succeeds.  On
       * failure it has already freed the container it took, so only the
       * ones still queued need releasing.
       */

      while (!sq_empty(&priv->pend))
        {
          struct sai_buffer_s *pending =
            (struct sai_buffer_s *)sq_remfirst(&priv->pend);

          apb_free(pending->apb);
          sai_buf_free(priv, pending);
        }

      priv->txenab = priv->rxenab = false;
      leave_critical_section(flags);
      nxmutex_unlock(&priv->lock);
      return ret;
    }

  leave_critical_section(flags);
  nxmutex_unlock(&priv->lock);
  return OK;

errout_with_lock:
  nxmutex_unlock(&priv->lock);
  sai_buf_free(priv, bfcontainer);
  return ret;
}

