786	#ifdef CONFIG_STM32F7_SAI_DMA
787	static int sai_dma_setup(struct stm32f7_sai_s *priv)
788	{
789	  struct sai_buffer_s *bfcontainer;
790	  struct ap_buffer_s *apb;
791	  uintptr_t samp;
792	  apb_samp_t nbytes;
793	  size_t ntransfers = 0;
794	  int ret;
795	
796	  /* If there is already an active transmission in progress, then bail
797	   * returning success.
798	   */
799	
800	  if (!sq_empty(&priv->act))
801	    {
802	      return OK;
803	    }
804	
805	  /* If there are no pending transfer, then bail returning success */
806	
807	  if (sq_empty(&priv->pend))
808	    {
809	      priv->txenab = priv->rxenab = false;
810	      return OK;
811	    }
812	
813	  /* Remove the pending transfer at the head of the pending queue. */
814	
815	  bfcontainer = (struct sai_buffer_s *)sq_remfirst(&priv->pend);
816	  DEBUGASSERT(bfcontainer && bfcontainer->apb);
817	
818	  apb = bfcontainer->apb;
819	
820	  /* Get the transfer information, accounting for any data offset */
821	
822	  samp = (uintptr_t)&apb->samp[apb->curbyte];
823	
824	  /* Configure the DMA */
825	
826	  if (priv->txenab)
827	    {
828	      nbytes = apb->nbytes - apb->curbyte;
829	
830	      switch (priv->datalen)
831	        {
832	          case 8:
833	            priv->dma_ccr = SAI_TXDMA8_CONFIG;
834	            ntransfers = nbytes;
835	            break;
836	
837	          case 16:
838	            priv->dma_ccr = SAI_TXDMA16_CONFIG;
839	            DEBUGASSERT((nbytes & 0x1) == 0);
840	            ntransfers = nbytes >> 1;
841	            break;
842	
843	          case 32:
844	            priv->dma_ccr = SAI_TXDMA32_CONFIG;
845	            DEBUGASSERT((nbytes & 0x3) == 0);
846	            ntransfers = nbytes >> 2;
847	            break;
848	        }
849	    }
850	  else if (priv->rxenab)
851	    {
852	      nbytes = apb->nmaxbytes - apb->curbyte;
853	
854	      switch (priv->datalen)
855	        {
856	          case 8:
857	            priv->dma_ccr = SAI_RXDMA8_CONFIG;
858	            ntransfers = nbytes;
859	            break;
860	
861	          case 16:
862	            priv->dma_ccr = SAI_RXDMA16_CONFIG;
863	            DEBUGASSERT((nbytes & 0x1) == 0);
864	            ntransfers = nbytes >> 1;
865	            break;
866	
867	          case 32:
868	            priv->dma_ccr = SAI_RXDMA32_CONFIG;
869	            DEBUGASSERT((nbytes & 0x3) == 0);
870	            ntransfers = nbytes >> 2;
871	            break;
872	        }
873	    }
874	
875	  DEBUGASSERT(ntransfers > 0);
876	
877	  stm32_dmasetup(priv->dma, priv->base + STM32F7_SAI_DR_OFFSET,
878	                 samp, ntransfers, priv->dma_ccr);
879	
880	  /* Add the container to the list of active DMAs */
881	
882	  sq_addlast((sq_entry_t *)bfcontainer, &priv->act);
883	
884	  /* Start the DMA, saving the container as the current active transfer */
885	
886	  stm32_dmastart(priv->dma, sai_dma_callback, priv, false);
887	
888	  /* Enable the transmitter */
889	
890	  sai_modifyreg(priv, STM32F7_SAI_CR1_OFFSET, 0, SAI_CR1_SAIEN);
891	
892	  /* Start a watchdog to catch DMA timeouts */
893	
894	  if (bfcontainer->timeout > 0)
895	    {
896	      ret = wd_start(&priv->dog, bfcontainer->timeout,
897	                     sai_timeout, (wdparm_t)priv);
898	
899	      /* Check if we have successfully started the watchdog timer.  Note
900	       * that we do nothing in the case of failure to start the timer.  We
901	       * are already committed to the DMA anyway.  Let's just hope that the
902	       * DMA does not hang.
903	       */
904	
905	      if (ret < 0)
906	        {
907	          i2serr("ERROR: wd_start failed: %d\n", ret);
908	        }
909	    }
910	
911	  return OK;
912	}
