1181	/****************************************************************************
1182	 * Name: sai_receive
1183	 *
1184	 * Description:
1185	 *   Receive a block of data from I2S.
1186	 *
1187	 * Input Parameters:
1188	 *   dev      - Device-specific state data
1189	 *   apb      - A pointer to the audio buffer in which to receive data
1190	 *   callback - A user provided callback function that will be called at
1191	 *              the completion of the transfer.  The callback will be
1192	 *              performed in the context of the worker thread.
1193	 *   arg      - An opaque argument that will be provided to the callback
1194	 *              when the transfer complete
1195	 *   timeout  - The timeout value to use.  The transfer will be canceled
1196	 *              and an ETIMEDOUT error will be reported if this timeout
1197	 *              elapsed without completion of the DMA transfer.  Units
1198	 *              are system clock ticks.  Zero means no timeout.
1199	 *

1200	 * Returned Value:
1201	 *   OK on success; a negated errno value on failure.  NOTE:  This function
1202	 *   only enqueues the transfer and returns immediately.  Success here only
1203	 *   means that the transfer was enqueued correctly.
1204	 *
1205	 *   When the transfer is complete, a 'result' value will be provided as
1206	 *   an argument to the callback function that will indicate if the transfer
1207	 *   failed.
1208	 *
1209	 ****************************************************************************/
1210	
1211	static int sai_receive(struct i2s_dev_s *dev, struct ap_buffer_s *apb,
1212	                       i2s_callback_t callback, void *arg, uint32_t timeout)
1213	{
1214	  struct stm32f7_sai_s *priv = (struct stm32f7_sai_s *)dev;
1215	  struct sai_buffer_s *bfcontainer;
1216	  uint32_t mode;
1217	  irqstate_t flags;
1218	  int ret;
1219	
1220	  DEBUGASSERT(priv && apb);
1221	  i2sinfo("apb=%p nbytes=%d arg=%p timeout=%" PRId32 "\n",
1222	          apb, apb->nbytes - apb->curbyte, arg, timeout);
1223	
1224	  /* Allocate a buffer container in advance */
1225	
1226	  bfcontainer = sai_buf_allocate(priv);
1227	  DEBUGASSERT(bfcontainer);
1228	
1229	  /* Get exclusive access to the SAI driver data */
1230	
1231	  nxmutex_lock(&priv->lock);
1232	
1233	  /* Verify not already TX'ing */
1234	
1235	  if (priv->txenab)
1236	    {
1237	      i2serr("ERROR: SAI has no receiver\n");
1238	      ret = -EAGAIN;
1239	      goto errout_with_lock;
1240	    }
1241	
1242	  mode = priv->syncen ? SAI_CR1_MODE_SLAVE_RX : SAI_CR1_MODE_MASTER_RX;
1243	  sai_modifyreg(priv, STM32F7_SAI_CR1_OFFSET, SAI_CR1_MODE_MASK, mode);
1244	  priv->rxenab = true;
1245	
1246	  /* Add a reference to the audio buffer */
1247	
1248	  apb_reference(apb);
1249	
1250	  /* Initialize the buffer container structure */
1251	
1252	  bfcontainer->callback = (void *)callback;
1253	  bfcontainer->timeout  = timeout;
1254	  bfcontainer->arg      = arg;
1255	  bfcontainer->apb      = apb;
1256	  bfcontainer->result   = -EBUSY;
1257	
1258	  /* Add the buffer container to the end of the pending queue */
1259	
1260	  flags = enter_critical_section();
1261	  sq_addlast((sq_entry_t *)bfcontainer, &priv->pend);
1262	
1263	  /* Then start the next transfer.  If there is already a transfer in
1264	   * progress, then this will do nothing.
1265	   */
1266	
1267	#ifdef CONFIG_STM32F7_SAI_DMA
1268	  ret = sai_dma_setup(priv);
1269	#endif
1270	  DEBUGASSERT(ret == OK);
1271	  leave_critical_section(flags);
1272	  nxmutex_unlock(&priv->lock);
1273	  return OK;
1274	
1275	errout_with_lock:
1276	  nxmutex_unlock(&priv->lock);
1277	  sai_buf_free(priv, bfcontainer);
1278	  return ret;
1279	}
